using System.Collections;
using System.Reflection;
namespace Axiom.Gameplay;
public sealed class WaitForSeconds {internal double Duration;public WaitForSeconds(double seconds){if(!double.IsFinite(seconds)||seconds<0)throw new ArgumentException("Invalid wait");Duration=seconds;}}
public sealed class WaitForSecondsRealtime {public double waitTime;public WaitForSecondsRealtime(double seconds){if(!double.IsFinite(seconds)||seconds<0)throw new ArgumentException("Invalid wait");waitTime=seconds;}}
public sealed class WaitUntil {internal Func<bool> Test;public WaitUntil(Func<bool> predicate){Test=predicate??throw new ArgumentNullException(nameof(predicate));}}
public sealed class WaitWhile {internal Func<bool> Test;public WaitWhile(Func<bool> predicate){Test=predicate??throw new ArgumentNullException(nameof(predicate));}}
public abstract class CustomYieldInstruction : IEnumerator {public abstract bool keepWaiting {get;}public object? Current=>null;public bool MoveNext()=>keepWaiting;public void Reset(){}}
public sealed class WaitForFixedUpdate {}
public sealed class WaitForEndOfFrame {}
public sealed class Coroutine {
 internal readonly Script Owner;internal readonly IEnumerator Routine;internal readonly Stack<IEnumerator> Stack=new();internal object? Waiting;internal double Until;internal int Frame;internal bool Done;
 internal Coroutine(Script owner,IEnumerator routine){Owner=owner;Routine=routine;Stack.Push(routine);}
}
internal static class RuntimeLifecycle {
 private static readonly HashSet<Script> Awakened=new(),Enabled=new(),Started=new();
 internal static readonly Dictionary<Type,(Func<Script> Create,string Path,Action<Script,System.Text.Json.JsonElement> Apply,Action<Script,System.Text.Json.Utf8JsonWriter> Write)> Factories=new();
 private static readonly List<Coroutine> Routines=new();
 private static readonly HashSet<Type> PhysicsTypes=new(),FixedTypes=new();internal static bool NeedsFixed=>Context.LiveScripts.Any(s=>s.isActiveAndEnabled&&(!Started.Contains(s)||FixedTypes.Contains(ScriptBridge.Type(s))));internal static bool NeedsPhysics=>Routines.Any(c=>!c.Done&&c.Waiting is WaitForFixedUpdate)||Context.LiveScripts.Any(s=>s.isActiveAndEnabled&&PhysicsTypes.Contains(ScriptBridge.Type(s)));
 private sealed record Invocation(Script Owner,string Name,Action Callback,double Due,double Repeat);
 private static readonly List<Invocation> Invocations=new();
 private static readonly List<(Object Target,double Due)> Destructions=new();
 internal static void DestroyAfter(Object? target,double delay){if(!double.IsFinite(delay)||delay<0)throw new ArgumentException("Invalid destruction delay");if(ReferenceEquals(target,null)||!target)return;if(target is Transform)throw new InvalidOperationException("Transform cannot be removed");if(target is not GameObject&&target is not Component)throw new NotSupportedException("Runtime asset destruction is not implemented");var index=Destructions.FindIndex(item=>item.Target==target);var due=Time.time+delay;if(index>=0){if(due<Destructions[index].Due)Destructions[index]=(target,due);return;}Destructions.RemoveAll(item=>!item.Target);if(Destructions.Count>=256)throw new InvalidOperationException("Destruction scheduling limit exceeded");Destructions.Add((target,due));}
 private static readonly HashSet<int> Destroying=new();
 internal static void DestroyNow(Object? target){if(ReferenceEquals(target,null)||!target)return;if(!Destroying.Add(target.GetInstanceID()))return;try{if(target is GameObject go)Context.Destroy(go.Entity);else if(target is Component component)Context.Remove(component);else throw new NotSupportedException("Runtime asset destruction is not implemented");}finally{Destroying.Remove(target.GetInstanceID());}}
 private static void FlushDestructions(){Destructions.RemoveAll(item=>!item.Target);for(var count=0;count<256;count++){var index=Destructions.FindIndex(item=>item.Due<=Time.time);if(index<0)return;var item=Destructions[index];Destructions.RemoveAt(index);DestroyNow(item.Target);}if(Destructions.Any(item=>item.Due<=Time.time))throw new InvalidOperationException("Destruction callback scheduling limit exceeded");}
 internal static void Reset(){UnityEngine.Object.ResetFacades();UnityEngine.AsyncInstantiationQueue.Reset();TransformGraph.Reset();PhysicsTypes.Clear();FixedTypes.Clear();Awakened.Clear();Enabled.Clear();Started.Clear();Destroying.Clear();foreach(var c in Routines.ToArray())Stop(c);Invocations.Clear();Destructions.Clear();Context.ObjectIdentities.Clear();Context.ComponentOrders.Clear();Context.ObjectEpochs.Clear();Context.ScriptPaths.Clear();Context.AddCompiledScript=Add;}
 internal static string PathOf(Script script)=>Context.ScriptPaths.GetValueOrDefault(script,"");
 internal static void Register<[System.Diagnostics.CodeAnalysis.DynamicallyAccessedMembers(System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.All)]T>(string path,Func<T> create,Action<object,System.Text.Json.JsonElement> apply,Action<object,System.Text.Json.Utf8JsonWriter> write) where T:class{Factories[typeof(T)]=(()=>ScriptBridge.Attach(create()!),path,(s,v)=>apply(ScriptBridge.Value(s),v),(s,w)=>write(ScriptBridge.Value(s),w));if((typeof(MonoBehaviour).IsAssignableFrom(typeof(T))||typeof(UnityEngine.MonoBehaviour).IsAssignableFrom(typeof(T)))&&typeof(T).GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Any(m=>m.Name=="FixedUpdate"&&m.DeclaringType!=typeof(UnityEngine.MonoBehaviour)&&m.DeclaringType!=typeof(MonoBehaviour)))FixedTypes.Add(typeof(T));if((typeof(MonoBehaviour).IsAssignableFrom(typeof(T))||typeof(UnityEngine.MonoBehaviour).IsAssignableFrom(typeof(T)))&&new[]{"OnCollisionEnter","OnCollisionStay","OnCollisionExit","OnTriggerEnter","OnTriggerStay","OnTriggerExit","OnCollisionEnter2D","OnCollisionStay2D","OnCollisionExit2D","OnTriggerEnter2D","OnTriggerStay2D","OnTriggerExit2D"}.Any(name=>typeof(T).GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Any(m=>m.Name==name&&m.DeclaringType!=typeof(UnityEngine.MonoBehaviour)&&m.DeclaringType!=typeof(MonoBehaviour))))PhysicsTypes.Add(typeof(T));}
 internal static void Initialize(){
  foreach(var s in Context.LiveScripts.ToArray())if(!Awakened.Contains(s)&&Context.Entities.ContainsKey(s.Entity.Id)&&Context.IsActive(s.Entity.Id)){Awakened.Add(s);ScriptBridge.Message(s,"Awake");}
  foreach(var s in Context.LiveScripts.ToArray())if(Awakened.Contains(s)&&!Enabled.Contains(s)&&s.isActiveAndEnabled){Enabled.Add(s);ScriptBridge.Message(s,"OnEnable");}
 }
 internal static void StartAll(){Initialize();foreach(var s in Context.LiveScripts.ToArray())if(s.isActiveAndEnabled&&Started.Add(s)){ScriptBridge.Message(s,"Start");s.OnStart();}}
 internal static void Update(double delta){UnityEngine.AsyncInstantiationQueue.Tick();StartAll();foreach(var s in Context.LiveScripts.ToArray())if(s.isActiveAndEnabled)s.OnUpdate(delta);AI.NavMesh.Tick(delta);Tick("update");}
 internal static void Fixed(){StartAll();Time.inFixedTimeStep=true;try{foreach(var s in Context.LiveScripts.ToArray())if(s.isActiveAndEnabled)ScriptBridge.Message(s,"FixedUpdate");}finally{Time.inFixedTimeStep=false;}}
 internal static void Physics(){Tick("fixed");}
 internal static void Late(){foreach(var s in Context.LiveScripts.ToArray())if(s.isActiveAndEnabled)ScriptBridge.Message(s,"LateUpdate");}
 internal static void End(){Tick("end");FlushDestructions();}
 internal static void Activation(){foreach(var s in Context.LiveScripts.ToArray()){var active=s.isActiveAndEnabled;if(active&&!Enabled.Contains(s)){Initialize();}else if(!active&&Enabled.Remove(s)){ScriptBridge.Message(s,"OnDisable");if(!Context.IsActive(s.Entity.Id))StopAll(s);}}}
 internal static void Remove(Script s){if(s.RuntimeRemoved)return;s.RuntimeRemoved=true;if(Enabled.Remove(s))ScriptBridge.Message(s,"OnDisable");StopAll(s);Invocations.RemoveAll(i=>i.Owner==s);s.OnStop();if(Awakened.Remove(s))ScriptBridge.Message(s,"OnDestroy");Started.Remove(s);}
 internal static Script Add(Type type,Entity entity){if(!Factories.TryGetValue(type,out var factory))throw new NotSupportedException("Script type is not compiled: "+type.Name);if(Context.LiveScripts.Count>=Limits.Attachments||Context.LiveScripts.Count(s=>s.Entity.Id==entity.Id)>=8||Context.LiveScripts.Any(s=>s.Entity.Id==entity.Id&&ScriptBridge.Type(s)==type))throw new InvalidOperationException("Duplicate script or attachment limit");var s=factory.Create();s.Entity=entity;Context.LiveScripts.Add(s);Context.ScriptPaths[s]=factory.Path;PublishComponents(entity);Initialize();return s;}
 internal static void PublishComponents(Entity entity){var list=new System.Text.Json.Nodes.JsonArray();foreach(var s in Context.LiveScripts.Where(s=>s.Entity.Id==entity.Id)){if(!Factories.TryGetValue(ScriptBridge.Type(s),out var f))continue;using var stream=new MemoryStream();using(var w=new System.Text.Json.Utf8JsonWriter(stream))f.Write(s,w);var component=new System.Text.Json.Nodes.JsonObject{["path"]=f.Path,["values"]=System.Text.Json.Nodes.JsonNode.Parse(stream.ToArray())};list.Add(component);}Context.Property(entity,"scriptComponents",list);}
 internal static void Clone(Script original,Entity entity){if(!Factories.TryGetValue(ScriptBridge.Type(original),out var f))throw new NotSupportedException("Cloning requires a compiled physical script");if(Context.LiveScripts.Count>=Limits.Attachments)throw new InvalidOperationException("Script attachment limit");var s=f.Create();s.Entity=entity;ScriptValues.Copy(ScriptBridge.Type(original),original,s);Context.LiveScripts.Add(s);Context.ScriptPaths[s]=f.Path;PublishComponents(entity);}

 internal static Coroutine Start(Script owner,IEnumerator routine){if(!owner.gameObject.activeInHierarchy)throw new InvalidOperationException("Cannot start coroutine on an inactive object");if(Routines.Count>=256)throw new InvalidOperationException("Coroutine limit exceeded");var c=new Coroutine(owner,routine??throw new ArgumentNullException(nameof(routine)));Routines.Add(c);Advance(c);return c;}
 internal static void Stop(Coroutine c){if(c.Done)return;c.Done=true;while(c.Stack.TryPop(out var e))(e as IDisposable)?.Dispose();Routines.Remove(c);}
 internal static void Stop(Script owner,IEnumerator routine){foreach(var c in Routines.Where(c=>c.Owner==owner&&c.Routine==routine).ToArray())Stop(c);}
 internal static void StopAll(Script? owner){if(owner==null)return;foreach(var c in Routines.Where(c=>c.Owner==owner).ToArray())Stop(c);}
 private static void Advance(Coroutine c){for(var moves=0;moves<128&&!c.Done;moves++){if(c.Stack.Count==0){Stop(c);return;}var e=c.Stack.Peek();if(!e.MoveNext()){c.Stack.Pop();(e as IDisposable)?.Dispose();continue;}var value=e.Current;if(value is IEnumerator nested&&value is not CustomYieldInstruction){if(c.Stack.Count>=32)throw new InvalidOperationException("Coroutine nesting limit");c.Stack.Push(nested);continue;}c.Waiting=value;c.Frame=Time.frameCount+1;c.Until=value switch {WaitForSeconds wait=>Time.time+wait.Duration,WaitForSecondsRealtime wait=>Time.unscaledTime+wait.waitTime,_=>0};return;}if(!c.Done)throw new InvalidOperationException("Coroutine made too many immediate advances");}
 internal static void Tick(string phase){if(phase=="update")foreach(var i in Invocations.ToArray())if(i.Due<=Time.time&&Context.Entities.ContainsKey(i.Owner.Entity.Id)){Invocations.Remove(i);if(i.Repeat>0&&Context.Entities.ContainsKey(i.Owner.Entity.Id))Invocations.Add(i with {Due=Time.time+i.Repeat});i.Callback();}
  foreach(var c in Routines.ToArray()){if(c.Done)continue;if(!Context.Entities.ContainsKey(c.Owner.Entity.Id)||!c.Owner.gameObject.activeInHierarchy){Stop(c);continue;}var ready=c.Waiting switch {WaitForFixedUpdate=>phase=="fixed",WaitForEndOfFrame=>phase=="end",_=>phase=="update"&&Time.frameCount>=c.Frame&&(c.Waiting switch {WaitForSeconds=>Time.time>=c.Until,WaitForSecondsRealtime=>Time.unscaledTime>=c.Until,WaitUntil wait=>wait.Test(),WaitWhile wait=>!wait.Test(),Coroutine other=>other.Done,AsyncOperation operation=>operation.isDone,UnityEngine.AsyncOperation operation=>operation.isDone,CustomYieldInstruction custom=>!custom.keepWaiting,null=>true,_=>throw new NotSupportedException("Unsupported coroutine yield type "+c.Waiting.GetType().Name)})};if(ready)Advance(c);}
 }
 internal static void Invoke(Script owner,string name,double delay,double repeat){if(!double.IsFinite(delay)||delay<0||!double.IsFinite(repeat)||repeat<0||Invocations.Count>=256)throw new ArgumentException("Invalid invocation or limit exceeded");var method=owner.GetType().GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,Type.EmptyTypes,null);if(method==null||method.ReturnType!=typeof(void))throw new ArgumentException("Invoke needs a compiled parameterless void method: "+name);Invocations.Add(new(owner,name,()=>method.Invoke(owner,null),Time.time+delay,repeat));}
 internal static void Cancel(Script owner,string? name)=>Invocations.RemoveAll(i=>i.Owner==owner&&(name==null||i.Name==name));
 internal static bool IsInvoking(Script owner,string? name)=>Invocations.Any(i=>i.Owner==owner&&(name==null||i.Name==name));
}
public abstract partial class MonoBehaviour {
 public Coroutine StartCoroutine(IEnumerator routine)=>RuntimeLifecycle.Start(this,routine);
 public void StopCoroutine(Coroutine coroutine){if(coroutine.Owner!=this)throw new ArgumentException("Coroutine belongs to another behaviour");RuntimeLifecycle.Stop(coroutine);}
 public void StopCoroutine(IEnumerator routine)=>RuntimeLifecycle.Stop(this,routine);
 public void StopAllCoroutines()=>RuntimeLifecycle.StopAll(this);
 public void Invoke(string methodName,double time)=>RuntimeLifecycle.Invoke(this,methodName,time,0);
 public void InvokeRepeating(string methodName,double time,double repeatRate){if(repeatRate<=0)throw new ArgumentException("Repeat rate must be positive");RuntimeLifecycle.Invoke(this,methodName,time,repeatRate);}
 public void CancelInvoke()=>RuntimeLifecycle.Cancel(this,null);
 public void CancelInvoke(string methodName)=>RuntimeLifecycle.Cancel(this,methodName);
 public bool IsInvoking()=>RuntimeLifecycle.IsInvoking(this,null);
 public bool IsInvoking(string methodName)=>RuntimeLifecycle.IsInvoking(this,methodName);
}
